import{_ as s,C as i,o as n,c as d,j as a,a as r,E as o,a2 as l}from"./chunks/framework.BxGh02fV.js";const k=JSON.parse('{"title":"Quality","description":"","frontmatter":{"title":"Quality"},"headers":[],"relativePath":"en/agent/qualite.md","filePath":"en/agent/qualite.md"}'),h={name:"en/agent/qualite.md"};function c(f,e,u,p,m,g){const t=i("Ask");return n(),d("div",null,[e[0]||(e[0]=a("h1",{id:"quality",tabindex:"-1"},[r("Quality "),a("a",{class:"header-anchor",href:"#quality","aria-label":'Permalink to "Quality"'},"​")],-1)),e[1]||(e[1]=a("p",null,"This path keeps the project consistent: code does not change without a task in progress, the registry does not contradict itself, and sub-agents do not write just anywhere. You come to it before a commit, after a long session, or to install the safeguards.",-1)),e[2]||(e[2]=a("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[r("What you ask the agent "),a("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(t,{say:"Is there any drift? I think I changed code without a task.",verb:"effortless_drift_check",family:"qualite"}),o(t,{say:"Install the hook that stops me from committing code without a task in progress.",verb:"effortless_drift_hook_install",family:"qualite"}),o(t,{say:"Check the registry's consistency: epics, stories, tasks.",verb:"effortless_validate_project",family:"qualite"}),o(t,{say:"What would you repair if we ran the repair? Don't touch anything yet.",verb:"effortless_health_repair",family:"qualite",args:'{"apply":false}'}),o(t,{say:"OK, apply the repairs.",verb:"effortless_health_repair",family:"qualite",args:'{"apply":true}'}),o(t,{say:"Confine the sub-agents: they must not write directly into the project.",verb:"effortless_confinement_hook_install",family:"qualite"}),o(t,{say:"Regenerate the registry of the code's focal points.",verb:"effortless_foyer_registry",family:"qualite"}),e[3]||(e[3]=l('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="detect-drift" tabindex="-1">Detect drift <a class="header-anchor" href="#detect-drift" aria-label="Permalink to &quot;Detect drift&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#drift-check"><code>effortless_drift_check</code></a> reads the git state of the project and of each stack that has its own repository. There is drift when code is modified while no task is <strong>In progress</strong>. Files in <code>.effortless/</code> and <code>blueprints/</code> do not count as code. The response also says whether the anti-drift hook is installed on every repository. The verb only reads.</p><h3 id="install-the-anti-drift-hook" tabindex="-1">Install the anti-drift hook <a class="header-anchor" href="#install-the-anti-drift-hook" aria-label="Permalink to &quot;Install the anti-drift hook&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#drift-hook-install"><code>effortless_drift_hook_install</code></a> installs a git <code>pre-commit</code> hook on the project&#39;s repository and on each stack that has its own repository. When code is staged with no task in progress, it refuses the commit. When a task is in progress, it shows which one will carry the commit. It never replaces a <code>pre-commit</code> hook that is not Effortless&#39;s.</p><h3 id="validate-the-registry" tabindex="-1">Validate the registry <a class="header-anchor" href="#validate-the-registry" aria-label="Permalink to &quot;Validate the registry&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#validate-project"><code>effortless_validate_project</code></a> audits epics, stories and tasks and returns the anomalies ranked by severity: blocking, wrong, probably forgotten, inherited from before a rule. It only reads.</p><h3 id="repair" tabindex="-1">Repair <a class="header-anchor" href="#repair" aria-label="Permalink to &quot;Repair&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#health-repair"><code>effortless_health_repair</code></a> makes the same diagnosis and announces what it would repair. Without <code>apply</code>, nothing is modified. With <code>apply: true</code>, it applies only the repairs that need no decision: closing a story whose tasks are all done, closing an epic whose stories are all closed. The rest stays in the anomalies. The agent announces first, then applies only after your agreement.</p><h3 id="confine-sub-agents" tabindex="-1">Confine sub-agents <a class="header-anchor" href="#confine-sub-agents" aria-label="Permalink to &quot;Confine sub-agents&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#confinement-hook-install"><code>effortless_confinement_hook_install</code></a> installs a hook that refuses a sub-agent the right to write directly into the project (file-writing tools). It works in a worktree, and its work enters the repository only at reintegration, when the bar is green (see <a href="/Effortless/en/agent/code.html">Code and stacks</a>). The script is placed in <code>.claude/hooks/</code> and declared in <code>.claude/settings.json</code>, which the verb completes without ever replacing it. The hook does not cover shell commands and does not confine the main agent.</p><h3 id="maintain-the-registry-of-focal-points" tabindex="-1">Maintain the registry of focal points <a class="header-anchor" href="#maintain-the-registry-of-focal-points" aria-label="Permalink to &quot;Maintain the registry of focal points&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/qualite.html#foyer-registry"><code>effortless_foyer_registry</code></a> scans the production code for marked focal points (&quot;foyers&quot;), and also returns its blind spot: files without a marker, public functions outside any focal point. By default (<code>write_page</code> absent or true), it writes the sealed page into the pages folder declared by the user documentation. With <code>write_page: false</code>, it returns the content without writing anything. The scan reads Rust files.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>A drift verdict and a list of files, the same as the <a href="/Effortless/en/guide/drift.html">Drift</a> screen: the agent and you see the same thing.</li><li>A <code>pre-commit</code> hook in the <code>.git/hooks/</code> of each tracked repository.</li><li>An anomaly report and, after agreement, closed epics and stories.</li><li>For confinement: <code>.claude/hooks/confine-subagents.cjs</code> and its entry in <code>.claude/settings.json</code>.</li><li>For focal points: a derived documentation page, or its content in the response.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>No Effortless project found from the working folder</td><td><code>mcp:racineProjetIntrouvable</code></td><td>Set <code>EFFORTLESS_PROJECT</code> if the project exists elsewhere, otherwise <code>effortless_init</code>.</td></tr><tr><td><code>pre-commit</code> hook already present and not Effortless&#39;s</td><td><code>drift:foreignHook</code></td><td>Remove or rename that hook, then run <code>effortless_drift_hook_install</code> again.</td></tr><tr><td>A repository to equip is not a git repository</td><td><code>drift:notAGitRepo</code></td><td>Run <code>git init</code> in that folder, or remove <code>git: true</code> from the stack.</td></tr><tr><td>Confinement hook file that is not ours</td><td><code>confinement:hookForeign</code></td><td>Remove or rename that file, then run <code>effortless_confinement_hook_install</code> again.</td></tr><tr><td><code>.claude/settings.json</code> is not a JSON object</td><td><code>confinement:settingsNotAnObject</code></td><td>Fix that file, then retry.</td></tr><tr><td>Folder that is not a valid Effortless project</td><td>&quot;Pas un projet Effortless valide.&quot;</td><td>Check <code>effortless.json</code>.</td></tr><tr><td>Focal-point registry: binary older than the repository&#39;s code</td><td><code>foyer:binairePerime</code></td><td>Rebuild (<code>cargo build --bin app</code>), then retry. This safeguard mostly concerns Effortless&#39;s own development repository.</td></tr><tr><td>Focal-point registry: no user documentation declared</td><td><code>userDoc:usage</code> (&quot;aucune stack ne porte de userdoc.json&quot;)</td><td>Declare a stack&#39;s user documentation (see <a href="/Effortless/en/agent/documentation.html">Documentation</a>), or ask for the content alone with <code>write_page: false</code>.</td></tr></tbody></table>',17))])}const b=s(h,[["render",c]]);export{k as __pageData,b as default};
